<?php
declare(strict_types=1); namespace App\Services; use CodeIgniter\Database\BaseConnection; use InvalidArgumentException; use RuntimeException;
final class WarehouseMovementService{private const TYPES=['ENTRY','EXIT','ADJUSTMENT'];public function __construct(private?BaseConnection$db=null,private?WarehouseStockService$stock=null){$this->db??=db_connect('default');$this->stock??=new WarehouseStockService($this->db);}public function createDraft(array$input,int$userId):int{$type=strtoupper(trim((string)($input['movement_type']??'')));if(!in_array($type,self::TYPES,true))throw new InvalidArgumentException('Tipo de movimiento no válido.');$wid=(int)($input['warehouse_id']??0);if(!$this->db->table('warehouses')->where(['id'=>$wid,'status'=>'active','deleted'=>0])->countAllResults())throw new InvalidArgumentException('Seleccione un almacén activo.');$lines=$input['lines']??[];if(!is_array($lines)||!$lines)throw new InvalidArgumentException('Agregue al menos un producto.');$normalized=[];foreach($lines as$l){$pid=(int)($l['warehouse_product_id']??0);if(!$this->db->table('warehouse_products')->where(['id'=>$pid,'status'=>'active','deleted'=>0])->countAllResults())throw new InvalidArgumentException('Seleccione productos de almacén activos.');if($type==='ADJUSTMENT'){$physical=$this->decimal($l['physical_quantity']??null,'Existencia física');$normalized[]=['warehouse_product_id'=>$pid,'quantity'=>$physical,'quantity_delta'=>'0.000000','physical_quantity'=>$physical,'notes'=>trim((string)($l['notes']??''))?:null];}else{$qty=$this->decimal($l['quantity']??null,'Cantidad');if(bccomp($qty,'0',6)<=0)throw new InvalidArgumentException('La cantidad debe ser mayor que cero.');$normalized[]=['warehouse_product_id'=>$pid,'quantity'=>$qty,'quantity_delta'=>$type==='ENTRY'?$qty:bcsub('0',$qty,6),'physical_quantity'=>null,'notes'=>trim((string)($l['notes']??''))?:null];}}$now=get_current_utc_time();$this->db->transBegin();try{$this->db->table('warehouse_movements')->insert(['folio'=>null,'movement_type'=>$type,'warehouse_id'=>$wid,'movement_date'=>$this->dateTime($input['movement_date']??''),'reference_type'=>trim((string)($input['reference_type']??''))?:null,'reference_id'=>($input['reference_id']??'')===''?null:(int)$input['reference_id'],'reference_text'=>trim((string)($input['reference_text']??''))?:null,'notes'=>trim((string)($input['notes']??''))?:null,'status'=>'draft','created_by'=>$userId?:null,'created_at'=>$now,'updated_at'=>$now]);$id=(int)$this->db->insertID();$prefix=['ENTRY'=>'ENT','EXIT'=>'SAL','ADJUSTMENT'=>'AJU'][$type];$this->db->table('warehouse_movements')->where('id',$id)->update(['folio'=>$prefix.'-'.str_pad((string)$id,6,'0',STR_PAD_LEFT)]);foreach($normalized as$l)$this->db->table('warehouse_movement_lines')->insert(['warehouse_movement_id'=>$id]+$l);$this->db->transCommit();return$id;}catch(\Throwable$e){$this->db->transRollback();throw$e;}}public function confirm(int$id,int$userId):void{$this->db->transBegin();try{$m=$this->db->query('SELECT * FROM '.$this->db->prefixTable('warehouse_movements').' WHERE id=? FOR UPDATE',[$id])->getRow();if(!$m)throw new InvalidArgumentException('El movimiento no existe.');if($m->status==='confirmed'){ $this->db->transCommit();return;}if($m->status!=='draft')throw new InvalidArgumentException('Sólo un borrador puede confirmarse.');$this->db->query('SELECT id FROM '.$this->db->prefixTable('warehouses').' WHERE id=? FOR UPDATE',[$m->warehouse_id]);$lines=$this->db->table('warehouse_movement_lines')->where('warehouse_movement_id',$id)->get()->getResult();if(!$lines)throw new InvalidArgumentException('El movimiento no contiene partidas.');$requested=[];foreach($lines as$l){$pid=(int)$l->warehouse_product_id;if($m->movement_type==='ADJUSTMENT'){$current=$this->stock->getStock($pid,(int)$m->warehouse_id);$delta=bcsub((string)$l->physical_quantity,$current,6);$this->db->table('warehouse_movement_lines')->where('id',$l->id)->update(['quantity_delta'=>$delta,'quantity'=>str_starts_with($delta,'-')?substr($delta,1):$delta]);}elseif($m->movement_type==='EXIT'){$requested[$pid]=bcadd($requested[$pid]??'0',(string)$l->quantity,6);}}foreach($requested as$pid=>$qty){$available=$this->stock->getStock((int)$pid,(int)$m->warehouse_id);if(bccomp($available,$qty,6)<0)throw new InvalidArgumentException('No existe cantidad suficiente en el almacén. Disponible: '.$available.'. Solicitado: '.$qty.'.');}$now=get_current_utc_time();$this->db->table('warehouse_movements')->where('id',$id)->update(['status'=>'confirmed','confirmed_by'=>$userId?:null,'confirmed_at'=>$now,'updated_at'=>$now]);$this->db->transCommit();}catch(\Throwable$e){$this->db->transRollback();throw$e;}}public function cancel(int$id,string$reason,int$userId):void{if(trim($reason)==='')throw new InvalidArgumentException('El motivo de cancelación es obligatorio.');$this->db->transBegin();try{$m=$this->db->query('SELECT * FROM '.$this->db->prefixTable('warehouse_movements').' WHERE id=? FOR UPDATE',[$id])->getRow();if(!$m)throw new InvalidArgumentException('El movimiento no existe.');if($m->status==='cancelled'){$this->db->transCommit();return;}if($m->status!=='confirmed')throw new InvalidArgumentException('Sólo un movimiento confirmado puede cancelarse.');$this->db->query('SELECT id FROM '.$this->db->prefixTable('warehouses').' WHERE id=? FOR UPDATE',[$m->warehouse_id]);if($m->movement_type==='ENTRY'){foreach($this->db->table('warehouse_movement_lines')->where('warehouse_movement_id',$id)->get()->getResult()as$l){$current=$this->stock->getStock((int)$l->warehouse_product_id,(int)$m->warehouse_id);if(bccomp(bcsub($current,(string)$l->quantity_delta,6),'0',6)<0)throw new InvalidArgumentException('No se puede cancelar: parte de la entrada ya fue consumida.');}}$now=get_current_utc_time();$this->db->table('warehouse_movements')->where('id',$id)->update(['status'=>'cancelled','cancelled_by'=>$userId?:null,'cancelled_at'=>$now,'cancellation_reason'=>trim($reason),'updated_at'=>$now]);$this->db->transCommit();}catch(\Throwable$e){$this->db->transRollback();throw$e;}}private function decimal(mixed$v,string$label):string{$v=str_replace(',','.',trim((string)$v));if(!preg_match('/^(?:0|[1-9]\d*)(?:\.\d{1,6})?$/',$v))throw new InvalidArgumentException($label.' debe ser decimal no negativo.');return bcadd($v,'0',6);}private function dateTime(mixed$v):string{$v=trim((string)$v);if($v==='')return get_current_utc_time();$v=str_replace('T',' ',$v);$d=\DateTimeImmutable::createFromFormat('Y-m-d H:i',$v)?:\DateTimeImmutable::createFromFormat('Y-m-d H:i:s',$v);if(!$d)throw new InvalidArgumentException('La fecha del movimiento no es válida.');return$d->format('Y-m-d H:i:s');}}
